UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"itineraryStops","0","whyOnRoute"}', '"Drei Abholpunkte decken die drei wichtigsten Hotelzonen Busans ab (KTX/Nampo, Seomyeon im Stadtzentrum, Haeundae am Strand), ohne dass Gäste morgens quer durch die Stadt fahren müssen. Die Reihenfolge Westen→Osten hält die Fahrstrecke des Busses so kurz wie möglich und bringt die Gruppe gegen 09:50 Uhr zu Haedong Yonggungsa — früh genug, um den stärksten Andrang der ankommenden Reisebusse zu vermeiden."'::jsonb, false),
  updated_at = NOW()
WHERE slug = 'busan-top-attractions-day-tour' AND locale = 'de'
  AND detail_payload #>> '{"itineraryStops","0","whyOnRoute"}' = 'Drei Abholpunkte decken die drei wichtigsten Hotelzonen Busans ab (KTX/Nampo, Seomyeon im Stadtzentrum, Haeundae am Strand), ohne dass Gäste morgens quer durch die Stadt fahren müssen. Die Reihenfolge Nordwesten→Osten hält die Fahrstrecke des Busses so kurz wie möglich und bringt die Gruppe gegen 10:00 Uhr zu Haedong Yonggungsa — früh genug, um den stärksten Andrang der ankommenden Reisebusse zu vermeiden.';

UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"itineraryStops","0","description"}', '"Die Abholung ist an drei zentralen Verkehrsknotenpunkten in Busan gebündelt, damit der Tag überschaubar bleibt und niemand kreuz und quer durch die Stadt fahren muss: **Busan Station (Linie 1)** für Gäste, die in der Nähe des KTX-Terminals oder im Viertel Choryang/Nampo-dong wohnen; **Seomyeon Station (Linien 1 & 2)** — Busans meistfrequentierter U-Bahn-Umsteigebahnhof, zentral für Gäste in Hotels im Stadtzentrum rund um das Lotte Hotel Busan oder die Seomyeon Medical Street; und **Haeundae Station (Linie 2)** für Gäste im Resort-Viertel direkt am Strand in der Nähe von Westin Josun, Park Hyatt oder Signiel Busan. \n\nDer Bus fährt alle drei Punkte nacheinander an (Busan Station Ausgang 4 um 08:10 Uhr, Seomyeon Station Ausgang 4 um 08:30 Uhr, Haeundae Station Ausgang 5 um 09:10 Uhr) und fährt dann nach Nordosten über die Küstenroute an der Gwangan-Brücke Richtung Gijang-gun zum ersten Stopp des Tages. \n\nGesamte Fahrzeit von der letzten Abholung bis Haedong Yonggungsa: ~30-40 Minuten, je nach Verkehr. Der Fahrer verteilt eine gedruckte Programmkarte auf Koreanisch und Englisch mit allen Zeiten; bitte seien Sie 5 Minuten vor der geplanten Zeit an Ihrem Abholpunkt, damit der Tag für die späteren Stopps UN-Gedenkfriedhof und Gamcheon im Zeitplan bleibt, die engere Öffnungszeiten haben."'::jsonb, false),
  updated_at = NOW()
WHERE slug = 'busan-top-attractions-day-tour' AND locale = 'de'
  AND detail_payload #>> '{"itineraryStops","0","description"}' = 'Die Abholung ist an drei zentralen Verkehrsknotenpunkten in Busan gebündelt, damit der Tag überschaubar bleibt und niemand kreuz und quer durch die Stadt fahren muss: **Busan Station (Linie 1)** für Gäste, die in der Nähe des KTX-Terminals oder im Viertel Choryang/Nampo-dong wohnen; **Seomyeon Station (Linien 1 & 2)** — Busans meistfrequentierter U-Bahn-Umsteigebahnhof, zentral für Gäste in Hotels im Stadtzentrum rund um das Lotte Hotel Busan oder die Seomyeon Medical Street; und **Haeundae Station (Linie 2)** für Gäste im Resort-Viertel direkt am Strand in der Nähe von Westin Josun, Park Hyatt oder Signiel Busan. 

Der Bus fährt alle drei Punkte nacheinander an (in der Regel zuerst Busan Station gegen 09:00 Uhr, Seomyeon gegen 09:15 Uhr, Haeundae gegen 09:30 Uhr) und fährt dann nach Nordosten über die Küstenroute an der Gwangan-Brücke Richtung Gijang-gun zum ersten Stopp des Tages. 

Gesamte Fahrzeit von der letzten Abholung bis Haedong Yonggungsa: ~30-40 Minuten, je nach Verkehr. Der Fahrer verteilt eine gedruckte Programmkarte auf Koreanisch und Englisch mit allen Zeiten; bitte seien Sie 5 Minuten vor der geplanten Zeit an Ihrem Abholpunkt, damit der Tag für die späteren Stopps UN-Gedenkfriedhof und Gamcheon im Zeitplan bleibt, die engere Öffnungszeiten haben.';

