UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"itineraryStops","0","whyOnRoute"}', '"Trois points de prise en charge couvrent les trois principales zones hôtelières de Busan (KTX/Nampo, Seomyeon en centre-ville, Haeundae en bord de mer), sans obliger les voyageurs à traverser la ville le matin. L''enchaînement ouest→est réduit la distance parcourue par l''autocar et dépose le groupe à Haedong Yonggungsa vers 09 h 50 — assez tôt pour devancer les arrivées les plus denses des bus de tourisme."'::jsonb, false),
  updated_at = NOW()
WHERE slug = 'busan-top-attractions-day-tour' AND locale = 'fr'
  AND detail_payload #>> '{"itineraryStops","0","whyOnRoute"}' = 'Trois points de prise en charge couvrent les trois principales zones hôtelières de Busan (KTX/Nampo, Seomyeon en centre-ville, Haeundae en bord de mer), sans obliger les voyageurs à traverser la ville le matin. L''enchaînement nord-ouest→est réduit la distance parcourue par l''autocar et dépose le groupe à Haedong Yonggungsa vers 10 h 00 — assez tôt pour devancer les arrivées les plus denses des bus de tourisme.';

UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"itineraryStops","0","description"}', '"La prise en charge est regroupée sur trois pôles de transport du centre de Busan afin de garder la journée fluide sans traverser la ville en tous sens : **Busan Station (ligne 1)** pour les voyageurs logés près du terminal KTX ou dans le quartier de Choryang/Nampo-dong ; **Seomyeon Station (lignes 1 et 2)** — la correspondance de métro la plus fréquentée de Busan, centrale pour les voyageurs séjournant dans les hôtels du centre-ville autour du Lotte Hotel Busan ou de la Seomyeon Medical Street ; et **Haeundae Station (ligne 2)** pour les voyageurs du quartier balnéaire près du Westin Josun, du Park Hyatt ou du Signiel Busan. \n\nL''autocar effectue les trois prises en charge à la suite (Busan Station sortie 4 à 08 h 10, Seomyeon Station sortie 4 à 08 h 30, Haeundae Station sortie 5 à 09 h 10), puis part vers le nord-est en empruntant la route côtière du pont Gwangan en direction de Gijang-gun, pour le premier arrêt de la journée. \n\nTrajet total entre la dernière prise en charge et Haedong Yonggungsa : ~30-40 minutes selon la circulation. Le chauffeur remettra une carte d''itinéraire imprimée coréen-anglais avec les horaires ; merci de vous présenter à votre point de prise en charge 5 minutes avant l''heure prévue, afin que la journée reste dans les temps pour les arrêts suivants à Cimetière commémoratif de l''ONU et Gamcheon, dont les créneaux d''ouverture sont plus stricts."'::jsonb, false),
  updated_at = NOW()
WHERE slug = 'busan-top-attractions-day-tour' AND locale = 'fr'
  AND detail_payload #>> '{"itineraryStops","0","description"}' = 'La prise en charge est regroupée sur trois pôles de transport du centre de Busan afin de garder la journée fluide sans traverser la ville en tous sens : **Busan Station (ligne 1)** pour les voyageurs logés près du terminal KTX ou dans le quartier de Choryang/Nampo-dong ; **Seomyeon Station (lignes 1 et 2)** — la correspondance de métro la plus fréquentée de Busan, centrale pour les voyageurs séjournant dans les hôtels du centre-ville autour du Lotte Hotel Busan ou de la Seomyeon Medical Street ; et **Haeundae Station (ligne 2)** pour les voyageurs du quartier balnéaire près du Westin Josun, du Park Hyatt ou du Signiel Busan. 

L''autocar effectue les trois prises en charge à la suite (généralement Busan Station en premier vers 09 h 00, Seomyeon vers 09 h 15, Haeundae vers 09 h 30), puis part vers le nord-est en empruntant la route côtière du pont Gwangan en direction de Gijang-gun, pour le premier arrêt de la journée. 

Trajet total entre la dernière prise en charge et Haedong Yonggungsa : ~30-40 minutes selon la circulation. Le chauffeur remettra une carte d''itinéraire imprimée coréen-anglais avec les horaires ; merci de vous présenter à votre point de prise en charge 5 minutes avant l''heure prévue, afin que la journée reste dans les temps pour les arrêts suivants à Cimetière commémoratif de l''ONU et Gamcheon, dont les créneaux d''ouverture sont plus stricts.';

