UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"itineraryStops","0","whyOnRoute"}', '"I tre punti di ritiro coprono le tre principali zone alberghiere di Busan (KTX/Nampo, Seomyeon nel centro città, Haeundae sul lungomare) senza costringere gli ospiti ad attraversare la città al mattino. La sequenza ovest→est riduce al minimo la distanza percorsa dal pullman e porta il gruppo a Haedong Yonggungsa intorno alle 09:50 — abbastanza presto da anticipare gli arrivi più affollati dei bus turistici."'::jsonb, false),
  updated_at = NOW()
WHERE slug = 'busan-top-attractions-day-tour' AND locale = 'it'
  AND detail_payload #>> '{"itineraryStops","0","whyOnRoute"}' = 'I tre punti di ritiro coprono le tre principali zone alberghiere di Busan (KTX/Nampo, Seomyeon nel centro città, Haeundae sul lungomare) senza costringere gli ospiti ad attraversare la città al mattino. La sequenza nordovest→est riduce al minimo la distanza percorsa dal pullman e porta il gruppo a Haedong Yonggungsa intorno alle 10:00 — abbastanza presto da anticipare gli arrivi più affollati dei bus turistici.';

UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"itineraryStops","0","description"}', '"Il ritiro è concentrato in tre snodi di trasporto nel centro di Busan per mantenere la giornata gestibile senza attraversare la città in ogni direzione: **stazione di Busan (Linea 1)** per gli ospiti che alloggiano vicino al terminal KTX o nella zona di Choryang/Nampo-dong; **stazione di Seomyeon (Linee 1 e 2)** — il nodo di interscambio della metropolitana più trafficato di Busan, comodo per gli ospiti negli hotel del centro città intorno al Lotte Hotel Busan o alla Seomyeon Medical Street; e **stazione di Haeundae (Linea 2)** per gli ospiti nel distretto turistico sul lungomare vicino a Westin Josun, Park Hyatt o Signiel Busan. \n\nIl pullman effettua il ritiro in tutti e tre i punti in sequenza (stazione di Busan Uscita 4 alle ore 8:10, stazione di Seomyeon Uscita 4 alle ore 8:30, stazione di Haeundae Uscita 5 alle ore 9:10) e prosegue poi verso nordest lungo il percorso costiero del Gwangan Bridge in direzione di Gijang-gun per la prima tappa della giornata. \n\nTrasferimento totale dall''ultimo ritiro a Haedong Yonggungsa: ~30-40 minuti a seconda del traffico. L''autista consegnerà una scheda itinerario stampata in coreano-inglese con gli orari; La preghiamo di trovarsi al Suo punto di ritiro 5 minuti prima dell''orario previsto, per mantenere la giornata in linea con le tappe successive di Cimitero commemorativo delle Nazioni Unite e Gamcheon, che hanno finestre di apertura più rigide."'::jsonb, false),
  updated_at = NOW()
WHERE slug = 'busan-top-attractions-day-tour' AND locale = 'it'
  AND detail_payload #>> '{"itineraryStops","0","description"}' = 'Il ritiro è concentrato in tre snodi di trasporto nel centro di Busan per mantenere la giornata gestibile senza attraversare la città in ogni direzione: **stazione di Busan (Linea 1)** per gli ospiti che alloggiano vicino al terminal KTX o nella zona di Choryang/Nampo-dong; **stazione di Seomyeon (Linee 1 e 2)** — il nodo di interscambio della metropolitana più trafficato di Busan, comodo per gli ospiti negli hotel del centro città intorno al Lotte Hotel Busan o alla Seomyeon Medical Street; e **stazione di Haeundae (Linea 2)** per gli ospiti nel distretto turistico sul lungomare vicino a Westin Josun, Park Hyatt o Signiel Busan. 

Il pullman effettua il ritiro in tutti e tre i punti in sequenza (di norma prima la stazione di Busan ~09:00, Seomyeon ~09:15, Haeundae ~09:30) e prosegue poi verso nordest lungo il percorso costiero del Gwangan Bridge in direzione di Gijang-gun per la prima tappa della giornata. 

Trasferimento totale dall''ultimo ritiro a Haedong Yonggungsa: ~30-40 minuti a seconda del traffico. L''autista consegnerà una scheda itinerario stampata in coreano-inglese con gli orari; La preghiamo di trovarsi al Suo punto di ritiro 5 minuti prima dell''orario previsto, per mantenere la giornata in linea con le tappe successive di Cimitero commemorativo delle Nazioni Unite e Gamcheon, che hanno finestre di apertura più rigide.';

