  detail_payload = jsonb_set(detail_payload, '{"whyTourWorks","routeLogicSections","1","items","2","detail"}', '"Ritiro alla stazione di Busan, a Seomyeon o a Haeundae — raggiungibili dalla maggior parte degli alloggi nel centro di Busan. Scelga l''uscita più vicina al Suo hotel; la durata effettiva del tour varia di circa 15 minuti a seconda di quella scelta."'::jsonb, false),
