UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"itineraryStops","0","whyOnRoute"}', '"Три точки посадки покрывают три главные гостиничные зоны Пусана (KTX/Нампхо, центральный Сомён, набережная Хэундэ), избавляя гостей от необходимости пересекать город утром. Порядок запад→восток минимизирует пробег автобуса и приводит группу к Хэдон Йонгунса около 09:50 — достаточно рано, чтобы опередить самый плотный поток туристических автобусов."'::jsonb, false),
  updated_at = NOW()
WHERE slug = 'busan-top-attractions-day-tour' AND locale = 'ru'
  AND detail_payload #>> '{"itineraryStops","0","whyOnRoute"}' = 'Три точки посадки покрывают три главные гостиничные зоны Пусана (KTX/Нампхо, центральный Сомён, набережная Хэундэ), избавляя гостей от необходимости пересекать город утром. Порядок северо-запад→восток минимизирует пробег автобуса и приводит группу к Хэдон Йонгунса около 10:00 — достаточно рано, чтобы опередить самый плотный поток туристических автобусов.';

UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"itineraryStops","0","description"}', '"Посадка сведена к трём центральным транспортным узлам Пусана, чтобы день оставался удобным и не пришлось пересекать город из конца в конец: **станция Пусан (линия 1)** — для гостей, живущих рядом с терминалом KTX или в районе Чхорян/Нампхо-дон; **станция Сомён (линии 1 и 2)** — самый загруженный пересадочный узел метро Пусана, удобный для гостей отелей в центре города рядом с Lotte Hotel Busan или медицинской улицей Сомёна; и **станция Хэундэ (линия 2)** — для гостей курортного района у пляжа рядом с Westin Josun, Park Hyatt или Signiel Busan. \n\nАвтобус забирает гостей во всех трёх точках по очереди (станция Пусан, выход 4 в 08:10, станция Сомён, выход 4 в 08:30, станция Хэундэ, выход 5 в 09:10), а затем направляется на северо-восток по прибрежному маршруту через мост Кванъан в сторону Киджан-гуна — к первой остановке дня. \n\nОбщее время в пути от последней точки посадки до Хэдон Йонгунса: ~30-40 минут в зависимости от трафика. Водитель раздаст печатную карточку маршрута с таймингом на корейском и английском языках; пожалуйста, будьте на своей точке посадки за 5 минут до назначенного времени, чтобы день шёл по плану — позже в программе Мемориальное кладбище ООН и Камчхон, у которых более строгие часы работы."'::jsonb, false),
  updated_at = NOW()
WHERE slug = 'busan-top-attractions-day-tour' AND locale = 'ru'
  AND detail_payload #>> '{"itineraryStops","0","description"}' = 'Посадка сведена к трём центральным транспортным узлам Пусана, чтобы день оставался удобным и не пришлось пересекать город из конца в конец: **станция Пусан (линия 1)** — для гостей, живущих рядом с терминалом KTX или в районе Чхорян/Нампхо-дон; **станция Сомён (линии 1 и 2)** — самый загруженный пересадочный узел метро Пусана, удобный для гостей отелей в центре города рядом с Lotte Hotel Busan или медицинской улицей Сомёна; и **станция Хэундэ (линия 2)** — для гостей курортного района у пляжа рядом с Westin Josun, Park Hyatt или Signiel Busan. 

Автобус забирает гостей во всех трёх точках по очереди (обычно сначала станция Пусан ~09:00, Сомён ~09:15, Хэундэ ~09:30), а затем направляется на северо-восток по прибрежному маршруту через мост Кванъан в сторону Киджан-гуна — к первой остановке дня. 

Общее время в пути от последней точки посадки до Хэдон Йонгунса: ~30-40 минут в зависимости от трафика. Водитель раздаст печатную карточку маршрута с таймингом на корейском и английском языках; пожалуйста, будьте на своей точке посадки за 5 минут до назначенного времени, чтобы день шёл по плану — позже в программе Мемориальное кладбище ООН и Камчхон, у которых более строгие часы работы.';

UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"whyTourWorks","routeLogicSections","1","items","2","detail"}', '"Посадка на станции Пусан, в Сомёне или в Хэундэ — удобно добраться из большинства отелей в центре Пусана. Выберите выход, ближайший к вашему отелю; фактическая продолжительность тура меняется примерно на 15 минут в зависимости от вашего выбора."'::jsonb, false),
